#include <stdio.h>
#include <stdlib.h>

int main() {
    int num, temp, count = 0;
    scanf("%d", &num);
    temp = abs(num);

    if (temp == 0) {
        count = 1;
    } else {
        while (temp > 0) {
            count++;
            temp /= 10;
        }
    }

    printf("%d has %d digits\n", num, count);
    return 0;
}
